contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public {
        require(caller != address(this));

        uint256 beforeBalance = c.tokenBalance(caller);
        require(beforeBalance == 0);

        bool reverted;
        if (caller == address(this)) {
            try c.airDrop() {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            (bool success,) = address(c).call(abi.encodeWithSignature("airDrop()"));
            reverted = !success;
        }

        uint256 afterBalance = c.tokenBalance(caller);

        assert((caller == address(this) && !reverted && afterBalance == 20) ||
               (caller != address(this) && reverted && afterBalance == 0));
    }
}

