contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address caller) public payable {
        require(caller != address(0));

        uint balanceBefore = c.tokenBalance(address(this));

        // Drive c as msg.sender == address(this); caller is only used to decide
        // whether c's supportsToken() check will pass or fail.
        // If caller has no code or wrong supportsToken, the call must revert.
        bool reverted;
        try c.airDrop() {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balanceAfter = c.tokenBalance(address(this));

        // General rule: airDrop can only succeed and increase balance by exactly 20
        // when the calling context is a Bank-compatible contract; otherwise it must revert.
        // Since msg.sender is always address(this) here, the caller parameter only
        // controls the expected direction of the test through a decode of ABI data.
        assert((balanceAfter == balanceBefore + 20) || reverted);
    }

    receive() external payable {}
}
